import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { FaUser, FaEnvelope, FaCalendar, FaTrophy, FaFire, FaClock, FaSignOutAlt, FaCamera, FaHeart, FaTrash, FaMars, FaVenus, FaUpload, FaImage, FaEdit, FaSave, FaTimes } from 'react-icons/fa';

function Profile() {
  const navigate = useNavigate();
  const [user, setUser] = useState({
    name: '',
    email: '',
    joined: '',
    avatar: null,
    avatarCategory: null
  });
  const [showAvatarPicker, setShowAvatarPicker] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [customImageUrl, setCustomImageUrl] = useState('');
  const [showUrlInput, setShowUrlInput] = useState(false);
  const [isEditingName, setIsEditingName] = useState(false);
  const [newName, setNewName] = useState('');

  // ============================================
  // 🔴 REPLACE THESE URLs WITH YOUR OWN IMAGE LINKS
  // ============================================
  
  // Boys Avatars - Add your image URLs here
  const boyAvatars = [
    { id: 1, url: 'https://randomuser.me/api/portraits/men/1.jpg', name: 'Alex' },
    { id: 2, url: 'https://randomuser.me/api/portraits/men/2.jpg', name: 'Ben' },
    { id: 3, url: 'https://randomuser.me/api/portraits/men/3.jpg', name: 'Charlie' },
    { id: 4, url: 'https://randomuser.me/api/portraits/men/4.jpg', name: 'David' },
    { id: 5, url: 'https://randomuser.me/api/portraits/men/5.jpg', name: 'Ethan' },
    { id: 6, url: 'https://randomuser.me/api/portraits/men/6.jpg', name: 'Frank' },
  ];

  // Girls Avatars - Add your image URLs here
  const girlAvatars = [
    { id: 1, url: 'https://randomuser.me/api/portraits/women/1.jpg', name: 'Emma' },
    { id: 2, url: 'https://randomuser.me/api/portraits/women/2.jpg', name: 'Sophia' },
    { id: 3, url: 'https://randomuser.me/api/portraits/women/3.jpg', name: 'Olivia' },
    { id: 4, url: 'https://randomuser.me/api/portraits/women/4.jpg', name: 'Ava' },
    { id: 5, url: 'https://randomuser.me/api/portraits/women/5.jpg', name: 'Mia' },
    { id: 6, url: 'https://randomuser.me/api/portraits/women/6.jpg', name: 'Isabella' },
  ];

  // Custom avatars
  const customAvatars = [
    { id: 1, url: 'https://i.pinimg.com/736x/a1/27/73/a1277303ec49ee936b2ba11bb3a98a18.jpg', name: 'cartoon avatar', category: 'cartoon' },
    { id: 2, url: 'https://i1-c.pinimg.com/1200x/67/ef/9d/67ef9d9bb1b009281379840a737c811f.jpg', name: 'cartoon avatar', category: 'cartoon' },
    { id: 3, url: 'https://cdn-icons-png.flaticon.com/512/1995/1995572.png', name: 'Animal 1', category: 'animal' },
    { id: 4, url: 'https://cdn-icons-png.flaticon.com/512/616/616408.png', name: 'Animal 2', category: 'animal' },
  ];

  useEffect(() => {
    const savedAvatar = localStorage.getItem('userAvatar');
    const savedCategory = localStorage.getItem('userAvatarCategory');
    const savedName = localStorage.getItem('userName');
    setUser({
      name: savedName || 'User',
      email: localStorage.getItem('userEmail') || 'user@example.com',
      joined: new Date().toLocaleDateString(),
      avatar: savedAvatar,
      avatarCategory: savedCategory
    });
    setNewName(savedName || 'User');
  }, []);

  const stats = [
    { icon: <FaFire color="#e74c3c" />, value: '12', label: 'Day Streak' },
    { icon: <FaTrophy color="#f39c12" />, value: '8', label: 'Badges Earned' },
    { icon: <FaClock color="#3498db" />, value: '245', label: 'Focus Minutes' },
    { icon: <FaHeart color="#e84393" />, value: '156', label: 'Moods Logged' },
  ];

  // Handle name edit
  const handleEditName = () => {
    setIsEditingName(true);
    setNewName(user.name);
  };

  const handleSaveName = () => {
    if (newName.trim()) {
      setUser({ ...user, name: newName.trim() });
      localStorage.setItem('userName', newName.trim());
      setIsEditingName(false);
    }
  };

  const handleCancelEdit = () => {
    setIsEditingName(false);
    setNewName(user.name);
  };

  // Handle image URL upload
  const handleUrlSubmit = () => {
    if (customImageUrl.trim()) {
      setUser({ ...user, avatar: customImageUrl, avatarCategory: 'custom' });
      localStorage.setItem('userAvatar', customImageUrl);
      localStorage.setItem('userAvatarCategory', 'custom');
      setShowAvatarPicker(false);
      setCustomImageUrl('');
      setShowUrlInput(false);
    }
  };

  // Handle image file upload
  const handleImageUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imageData = reader.result;
        setUser({ ...user, avatar: imageData, avatarCategory: 'uploaded' });
        localStorage.setItem('userAvatar', imageData);
        localStorage.setItem('userAvatarCategory', 'uploaded');
        setShowAvatarPicker(false);
      };
      reader.readAsDataURL(file);
    }
  };

  // Handle boy/girl avatar selection
  const handleAvatarSelect = (avatarUrl, category) => {
    setUser({ ...user, avatar: avatarUrl, avatarCategory: category });
    localStorage.setItem('userAvatar', avatarUrl);
    localStorage.setItem('userAvatarCategory', category);
    setShowAvatarPicker(false);
    setSelectedCategory(null);
  };

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userAvatar');
    localStorage.removeItem('userAvatarCategory');
    navigate('/');
  };

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Profile</h1>
          <p style={styles.subtitle}>Manage your account and view your progress</p>
        </div>

        {/* Avatar Card */}
        <div style={styles.avatarCard}>
          <div style={styles.avatarContainer}>
            {/* Avatar Display */}
            <div style={styles.avatarWrapper}>
              {user.avatar ? (
                <img src={user.avatar} alt="Avatar" style={styles.avatarImage} />
              ) : (
                <div style={styles.avatarPlaceholder}>
                  <FaUser size={50} color="#ccc" />
                </div>
              )}
              
              {/* Edit Button */}
              <button 
                style={styles.editAvatarBtn}
                onClick={() => setShowAvatarPicker(!showAvatarPicker)}
              >
                <FaCamera size={16} />
              </button>
            </div>

            {/* Name with Edit Option */}
            <div style={styles.nameContainer}>
              {isEditingName ? (
                <div style={styles.editNameContainer}>
                  <input
                    type="text"
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                    style={styles.nameInput}
                    autoFocus
                    onKeyPress={(e) => e.key === 'Enter' && handleSaveName()}
                  />
                  <button onClick={handleSaveName} style={styles.saveNameBtn}>
                    <FaSave />
                  </button>
                  <button onClick={handleCancelEdit} style={styles.cancelNameBtn}>
                    <FaTimes />
                  </button>
                </div>
              ) : (
                <div style={styles.nameDisplay}>
                  <h2 style={styles.userName}>{user.name}</h2>
                  <button onClick={handleEditName} style={styles.editNameBtn}>
                    <FaEdit size={16} />
                  </button>
                </div>
              )}
            </div>

            <div style={styles.userInfo}>
              <div style={styles.infoRow}><FaEnvelope /> {user.email}</div>
              <div style={styles.infoRow}><FaCalendar /> Joined {user.joined}</div>
            </div>
          </div>

          {/* Avatar Picker Popup */}
          {showAvatarPicker && (
            <div style={styles.avatarPicker}>
              <div style={styles.pickerHeader}>
                <h4>Choose Your Avatar</h4>
                <button onClick={() => setShowAvatarPicker(false)} style={styles.closeBtn}>✕</button>
              </div>
              
              {/* Upload Options */}
              <div style={styles.uploadSection}>
                {/* Upload File */}
                <label style={styles.uploadBtn}>
                  <FaUpload /> Upload Photo
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    style={{ display: 'none' }}
                  />
                </label>

                {/* OR Enter URL */}
                <button 
                  style={styles.urlBtn}
                  onClick={() => setShowUrlInput(!showUrlInput)}
                >
                  <FaImage /> Use Image URL
                </button>
              </div>

              {/* URL Input */}
              {showUrlInput && (
                <div style={styles.urlInputContainer}>
                  <input
                    type="text"
                    placeholder="Paste image URL here..."
                    value={customImageUrl}
                    onChange={(e) => setCustomImageUrl(e.target.value)}
                    style={styles.urlInput}
                  />
                  <button onClick={handleUrlSubmit} style={styles.urlSubmitBtn}>
                    Add
                  </button>
                </div>
              )}

              {/* Category Selection */}
              {!selectedCategory ? (
                <>
                  <div style={styles.categoryGrid}>
                    <div style={styles.categoryCard} onClick={() => setSelectedCategory('boys')}>
                      <div style={styles.categoryIcon}><FaMars size={40} color="#3498db" /></div>
                      <h4>Boys</h4>
                      <p>Choose from boy avatars</p>
                    </div>
                    <div style={styles.categoryCard} onClick={() => setSelectedCategory('girls')}>
                      <div style={styles.categoryIcon}><FaVenus size={40} color="#e84393" /></div>
                      <h4>Girls</h4>
                      <p>Choose from girl avatars</p>
                    </div>
                  </div>

                  {/* Custom Avatars Section */}
                  <div style={styles.customSection}>
                    <h4 style={styles.customTitle}>🎨 More Avatars</h4>
                    <div style={styles.avatarGrid}>
                      {customAvatars.map((avatar) => (
                        <div
                          key={avatar.id}
                          style={styles.avatarOption}
                          onClick={() => handleAvatarSelect(avatar.url, avatar.category)}
                        >
                          <img src={avatar.url} alt={avatar.name} style={styles.avatarOptionImage} />
                          <span style={styles.avatarOptionName}>{avatar.name}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </>
              ) : (
                <>
                  <button 
                    onClick={() => setSelectedCategory(null)} 
                    style={styles.backBtn}
                  >
                    ← Back to Categories
                  </button>
                  <div style={styles.avatarGrid}>
                    {(selectedCategory === 'boys' ? boyAvatars : girlAvatars).map((avatar) => (
                      <div
                        key={avatar.id}
                        style={styles.avatarOption}
                        onClick={() => handleAvatarSelect(avatar.url, selectedCategory)}
                      >
                        <img src={avatar.url} alt={avatar.name} style={styles.avatarOptionImage} />
                        <span style={styles.avatarOptionName}>{avatar.name}</span>
                      </div>
                    ))}
                  </div>
                </>
              )}

              {/* Remove Avatar Option */}
              {user.avatar && (
                <button onClick={() => {
                  setUser({ ...user, avatar: null, avatarCategory: null });
                  localStorage.removeItem('userAvatar');
                  localStorage.removeItem('userAvatarCategory');
                  setShowAvatarPicker(false);
                }} style={styles.removeBtn}>
                  <FaTrash /> Remove Avatar
                </button>
              )}
            </div>
          )}
        </div>

        {/* Stats Grid */}
        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={styles.statIcon}>{stat.icon}</div>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Menu Card */}
        <div style={styles.menuCard}>
          <h3 style={styles.menuTitle}>Settings</h3>
          <button onClick={handleLogout} style={styles.logoutBtn}>
            <FaSignOutAlt /> Logout
          </button>
        </div>
      </div>
    </div>
  );
}

